const cmds = [
  ["agent-help", ["entire","agent-help"]],
  ["entire-status", ["entire","status","--json"]],
  ["graph-version", ["entire","graph","version"]],
  ["worktrees", ["git","worktree","list","--porcelain"]],
  ["git-status", ["git","status","--short","--branch"]],
  ["instructions", ["rg","--files","-g","AGENTS.md","-g","CLAUDE.md",".",".."]]
];
const out = await Promise.all(cmds.map(async ([name,args]) => {
  const r = await tools.exec_command({cmd: args.map(x=>JSON.stringify(x)).join(" "), workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups", yield_time_ms:10000, max_output_tokens:12000});
  return `### ${name}\n${r.output}\n(exit ${r.exit_code ?? "running"})`;
}));
text(out.join("\n"));

const paths = [
  "/Users/muskanpaliwal/.codex/skills/hub/entire-review/references/review-rules.md",
  "/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups/CLAUDE.md",
  "/Users/muskanpaliwal/Work/open-source/entire/cli/AGENTS.md"
];
for (const p of paths) {
  const r = await tools.exec_command({cmd:`sed -n '1,400p' ${JSON.stringify(p)}`,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",yield_time_ms:10000,max_output_tokens:30000});
  text(`### ${p}\n${r.output}`);
}

const files = [
  ["/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups/CLAUDE.md", 401],
  ["/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups/.entire/graph-agent.md", 1]
];
for (const [p,start] of files) {
  const wc = await tools.exec_command({cmd:`wc -l ${JSON.stringify(p)}`,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",yield_time_ms:10000,max_output_tokens:1000});
  const r = await tools.exec_command({cmd:`sed -n '${start},1200p' ${JSON.stringify(p)}`,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",yield_time_ms:10000,max_output_tokens:50000});
  text(`### ${p}\n${wc.output}${r.output}`);
}

const ranges = [[401,750],[751,1100],[1101,1450],[1451,1800],[1801,2200]];
for (const [a,b] of ranges) {
  const r = await tools.exec_command({cmd:`sed -n '${a},${b}p' CLAUDE.md`,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",yield_time_ms:10000,max_output_tokens:18000});
  text(`### CLAUDE ${a}-${b}\n${r.output}`);
}

const specs = [
  {name:"pr",cmd:"gh pr view 2404 --repo entireio/cli --json number,title,state,isDraft,mergeable,mergeStateStatus,headRefOid,baseRefOid,headRefName,baseRefName,author,reviews,statusCheckRollup,comments,url"},
  {name:"checks",cmd:"gh pr checks 2404 --repo entireio/cli"},
  {name:"checkpoint-help",cmd:"entire agent-help checkpoint"},
  {name:"session",cmd:"entire session current --json"},
  {name:"graph-search",cmd:"entire graph search --repo . --profile full --format agent --top-k 10 --query \"pre-push repair oversized checkpoint metadata and warn linked worktree missing portable Entire Claude setup\""},
  {name:"scope",cmd:"git diff --stat HEAD"},
  {name:"numstat",cmd:"git diff --numstat HEAD"},
  {name:"dependency-stat",cmd:"git diff --stat 8a43e78f1e7f8567e2bd77b058c5155893e58cb0..HEAD"}
];
const out = await Promise.all(specs.map(async s => {
  const r = await tools.exec_command({cmd:s.cmd,workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",yield_time_ms:10000,max_output_tokens:s.name==="pr"?30000:12000});
  return `### ${s.name}\n${r.output}\n(exit ${r.exit_code ?? "running"})`;
}));
text(out.join("\n"));

const results = await Promise.all([
  tools.exec_command({
    cmd:"gh pr view 2404 --repo entireio/cli --json number,title,state,isDraft,mergeable,mergeStateStatus,headRefOid,baseRefOid,headRefName,baseRefName,author,reviews,statusCheckRollup,comments,url",
    workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",
    yield_time_ms:30000,
    max_output_tokens:30000,
    sandbox_permissions:"require_escalated",
    justification:"May I query GitHub to verify PR #2404’s current head, review state, comments, and checks before relying on the local stacked base?",
    prefix_rule:["gh","pr","view","2404","--repo","entireio/cli"]
  }),
  tools.exec_command({
    cmd:"gh pr checks 2404 --repo entireio/cli",
    workdir:"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-checkpoint-metadata-followups",
    yield_time_ms:30000,
    max_output_tokens:12000,
    sandbox_permissions:"require_escalated",
    justification:"May I query GitHub to verify PR #2404’s live CI and review-gate results?",
    prefix_rule:["gh","pr","checks","2404","--repo","entireio/cli"]
  })
]);
text(`### PR\n${results[0].output}\n(exit ${results[0].exit_code})\n### Checks\n${results[1].output}\n(exit ${results[1].exit_code})`);

