func TestDoctor_WorktreeWithoutSettingsDoesNotReportHealthyHooks(t *testing.T) {
	linkedRoot := setupClaudeWorktrees(t, testSettingsEnabled, true)
	enterWorktree(t, linkedRoot)
	issue := inspectWorktreeSetup(t.Context())
