func TestFetchAndRebase_RepairedRemoteWithRemoteOnlySuffixReplaysLocalSuffix(t *testing.T) {
	dir, repo, cleanRoot, _, sharedTip := bloatedV1Fixture(t)
	t.Chdir(dir)
	ctx := context.Background()

	localPath := "22/3333333333/0/metadata.json"
