	files["ee/ffffffffff/0/"+paths.TranscriptFileName] = []byte(`{"role":"user"}` + "\n")
	c3 = testutil.CommitFiles(t, r, []plumbing.Hash{c2}, files, "Checkpoint: eeffffffffff")
