		}

		if err := ctx.Err(); err != nil {
			return false, fmt.Errorf("scan local checkpoint metadata: %w", err)
		}
		fields := strings.Fields(record)
		if len(fields) < 5 {
			return false, fmt.Errorf("parse checkpoint metadata scan record %q", record)
